+        const update = (dt) => {
+          clock += dt;
+          for (const p of petals) {
+            if (p.state === "out") {
+              p.wait -= dt;
+              if (p.wait <= 0) { p.state = "grow"; p.timer = 0; p.s = 0.001; }
